package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static org.junit.jupiter.api.Assertions.*;
import static com.microsoft.playwright.assertions.PlaywrightAssertions.assertThat;
import com.microsoft.playwright.*;
import com.microsoft.playwright.options.AriaRole;
import java.nio.file.Path;

final class RiskAssessmentsBrowserAcceptance {
 static void change(Page p,String state){p.locator("select[name=state]").selectOption(state);p.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save changes →")).press("Enter");}
 static void run(BrowserTest h)throws Exception{
  String group;try(var db=h.store.open()){PlatformFoundationTest.bind(db);for(String name:new String[]{"RiskBrowserAssessor","RiskBrowserOwner"})Service.createAccount(db,map("name",name,"role","agent","password",WorkflowSupport.PASSWORD));group=Service.create(db,"sys_user_group",map("short_description","Risk treatment browser team"),"admin").get("sys_id").toString();db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",group,RecordAccess.owner(db,"RiskBrowserAssessor"));db.connection.commit();}
  try(var playwright=Playwright.create();var browser=playwright.chromium().launch();var ac=browser.newContext();var oc=browser.newContext()){
   var assessor=ac.newPage();h.login(assessor,"RiskBrowserAssessor");assessor.navigate(h.base()+"/workspace/risk");assessor.locator("a[href='/record/risk/new']").press("Enter");assertThat(assessor.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Assess and treat risk"))).hasCount(0);assessor.getByLabel("Risk summary",new Page.GetByLabelOptions().setExact(true)).fill("Supplier interruption <script>");assessor.getByLabel("Risk description",new Page.GetByLabelOptions().setExact(true)).fill("Review the exposure from a single supply route");assessor.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Create record →")).press("Enter");String id=assessor.url().substring(assessor.url().lastIndexOf('/')+1);change(assessor,"assess");assessor.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Assess and treat risk")).press("Enter");assessor.getByLabel("Inherent likelihood",new Page.GetByLabelOptions().setExact(true)).fill("4");assessor.getByLabel("Inherent impact",new Page.GetByLabelOptions().setExact(true)).fill("5");assessor.getByLabel("Residual likelihood",new Page.GetByLabelOptions().setExact(true)).fill("2");assessor.getByLabel("Residual impact",new Page.GetByLabelOptions().setExact(true)).fill("3");assessor.getByLabel("Risk response",new Page.GetByLabelOptions().setExact(true)).selectOption("mitigate");assessor.getByLabel("Assessment rationale").fill("Single supplier dependency <script>");assessor.getByLabel("Treatment or acceptance plan").fill("Qualify and verify an alternative supplier");assessor.getByLabel("Risk owner username").fill("RiskBrowserOwner");assessor.getByLabel("Review date").fill("2030-12-31");assessor.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save risk assessment")).press("Enter");assertThat(assessor.locator("main")).containsText("Inherent score: 20 / 25 · Residual score: 6 / 25");ReleaseBrowserAcceptance.accessible(assessor);assessor.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/risk-assessment-light.png")).setFullPage(true));
   assessor.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Risk workspace").setExact(true)).press("Enter");change(assessor,"respond");assessor.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Assess and treat risk")).press("Enter");assessor.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Coordinate treatment tasks")).press("Enter");assertThat(assessor.locator(".breadcrumb")).containsText("Risks");assessor.getByLabel("Task summary",new Page.GetByLabelOptions().setExact(true)).fill("Verify supplier qualification");assessor.getByLabel("Task instructions",new Page.GetByLabelOptions().setExact(true)).fill("Verify the alternate route and keep a clear outcome");assessor.getByLabel("Responsible team",new Page.GetByLabelOptions().setExact(true)).selectOption(group);assessor.getByLabel("Completion requirement",new Page.GetByLabelOptions().setExact(true)).selectOption("true");assessor.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Create work task")).press("Enter");assessor.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Claim task").setExact(true)).press("Enter");assessor.getByLabel("Completion outcome").fill("Alternative route qualification completed");assessor.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Complete task").setExact(true)).press("Enter");assessor.navigate(h.base()+"/record/risk/"+id+"/assessment");assessor.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Request or review monitoring")).press("Enter");assessor.getByLabel("Reviewer username").fill("RiskBrowserOwner");assessor.locator("select[name=target_state]").selectOption("monitor");assessor.getByLabel("Reason for review").fill("Review assessed exposure and completed supplier qualification");assessor.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Request review").setExact(true)).press("Enter");
   var owner=oc.newPage();h.login(owner,"RiskBrowserOwner");owner.navigate(h.base()+"/record/risk/"+id+"/assessment");assertThat(owner.locator("main")).containsText("Qualify and verify an alternative supplier");owner.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Request or review monitoring")).press("Enter");owner.getByLabel("Decision",new Page.GetByLabelOptions().setExact(true)).selectOption("approved");owner.getByLabel("Review comment").fill("Treatment outcome and residual exposure accepted for monitoring");owner.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Record decision")).press("Enter");assessor.navigate(h.base()+"/record/risk/"+id);change(assessor,"monitor");assessor.getByRole(AriaRole.LINK,new Page.GetByRoleOptions().setName("Assess and treat risk")).press("Enter");assertThat(assessor.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Save risk assessment"))).hasCount(0);assessor.getByRole(AriaRole.BUTTON,new Page.GetByRoleOptions().setName("Dark mode").setExact(true)).press("Enter");assessor.setViewportSize(390,844);ReleaseBrowserAcceptance.accessible(assessor);assertEquals(false,assessor.evaluate("document.documentElement.scrollWidth>window.innerWidth"));assertThat(assessor.locator("main script")).hasCount(0);assessor.screenshot(new Page.ScreenshotOptions().setPath(Path.of("target/risk-monitoring-dark.png")).setFullPage(true));
  }
 }
}
